-- VELOOP Task 01 supplemental synthetic test pack analysis
-- SIMULATED DATA — CREATED FOR ANALYTICAL TESTING. Not production metrics.
-- Run against the local SQLite DB generated by analyze_synthetic_pack.py.
-- The separate Task 02 workbook is deliberately excluded.

-- Dataset record counts
SELECT 'task_activity' AS dataset, COUNT(*) AS records, COUNT(DISTINCT activity_id) AS distinct_ids FROM task_activity
UNION ALL SELECT 'rewards', COUNT(*), COUNT(DISTINCT reward_id) FROM rewards
UNION ALL SELECT 'wallet', COUNT(*), COUNT(DISTINCT transaction_id) FROM wallet
UNION ALL SELECT 'withdrawals', COUNT(*), COUNT(DISTINCT withdrawal_id) FROM withdrawals
UNION ALL SELECT 'referrals', COUNT(*), COUNT(DISTINCT referral_id) FROM referrals
UNION ALL SELECT 'feature_events', COUNT(*), COUNT(DISTINCT event_id) FROM feature_events
UNION ALL SELECT 'messy_data', COUNT(*), COUNT(DISTINCT activity_id) FROM messy_data;

-- Status distributions: counts only, not production rates
SELECT task_status, COUNT(*) AS records FROM task_activity GROUP BY task_status ORDER BY records DESC;
SELECT unit, reward_status, COUNT(*) AS records, ROUND(SUM(amount),2) AS amount_sum FROM rewards GROUP BY unit, reward_status ORDER BY unit, reward_status;
SELECT unit, transaction_type, status, COUNT(*) AS records, ROUND(SUM(amount),2) AS signed_amount_sum FROM wallet GROUP BY unit, transaction_type, status ORDER BY unit, transaction_type, status;
SELECT status, COUNT(*) AS records FROM withdrawals GROUP BY status ORDER BY records DESC;
SELECT status, COUNT(*) AS records FROM referrals GROUP BY status ORDER BY records DESC;
SELECT feature, event_status, COUNT(*) AS records FROM feature_events GROUP BY feature, event_status ORDER BY feature, event_status;

-- Example synthetic KPI feasibility check; this is not a company completion rate.
SELECT COUNT(*) AS task_activity_rows,
       SUM(CASE WHEN task_started_at IS NOT NULL THEN 1 ELSE 0 END) AS rows_with_start,
       SUM(CASE WHEN task_status='completed' THEN 1 ELSE 0 END) AS completed_status_rows,
       ROUND(100.0*SUM(CASE WHEN task_status='completed' THEN 1 ELSE 0 END)/
       NULLIF(SUM(CASE WHEN task_started_at IS NOT NULL THEN 1 ELSE 0 END),0),2) AS completed_status_share_pct
FROM task_activity;

-- User, task, reward and reversal relationships
SELECT COUNT(*) AS unmatched_task_users FROM task_activity c LEFT JOIN task01_users_clean p ON c.user_id=p.user_id WHERE p.user_id IS NULL;
SELECT COUNT(*) AS unmatched_reward_users FROM rewards c LEFT JOIN task01_users_clean p ON c.user_id=p.user_id WHERE p.user_id IS NULL;
SELECT COUNT(*) AS unmatched_reward_activity FROM rewards c LEFT JOIN task_activity p ON c.source_activity_id=p.activity_id WHERE c.source_activity_id IS NOT NULL AND p.activity_id IS NULL;
SELECT COUNT(*) AS unmatched_reward_correction FROM rewards c LEFT JOIN rewards p ON c.correction_of_reward_id=p.reward_id WHERE c.correction_of_reward_id IS NOT NULL AND p.reward_id IS NULL;
SELECT COUNT(*) AS unmatched_wallet_reversal FROM wallet c LEFT JOIN wallet p ON c.reversal_of_transaction_id=p.transaction_id WHERE c.reversal_of_transaction_id IS NOT NULL AND p.transaction_id IS NULL;
SELECT COUNT(*) AS self_referrals FROM referrals WHERE referrer_user_id=referred_user_id;

-- Wallet references are polymorphic; broad known-reference check only.
WITH known_refs AS (
  SELECT reward_id AS reference_id FROM rewards
  UNION SELECT withdrawal_id FROM withdrawals
  UNION SELECT reference_id FROM external_references
)
SELECT COUNT(*) AS unmatched_wallet_reference_rows
FROM wallet w LEFT JOIN known_refs k ON w.reference_id=k.reference_id
WHERE w.reference_id IS NOT NULL AND k.reference_id IS NULL;

-- Chronology checks after QA corrections; expected zero
SELECT COUNT(*) AS task_completed_before_started FROM task_activity
WHERE task_completed_at IS NOT NULL AND task_started_at IS NOT NULL AND datetime(task_completed_at)<datetime(task_started_at);
SELECT COUNT(*) AS withdrawal_final_before_processing FROM withdrawals
WHERE final_at IS NOT NULL AND processing_at IS NOT NULL AND datetime(final_at)<datetime(processing_at);
SELECT COUNT(*) AS referral_activation_before_registration FROM referrals
WHERE activated_at IS NOT NULL AND registered_at IS NOT NULL AND datetime(activated_at)<datetime(registered_at);

-- Intentional defects in the separate Messy_Data test sheet
SELECT
  SUM(CASE WHEN activity_id IS NULL THEN 1 ELSE 0 END) AS missing_activity_ids,
  COUNT(*)-COUNT(DISTINCT activity_id)-SUM(CASE WHEN activity_id IS NULL THEN 1 ELSE 0 END) AS duplicate_nonnull_activity_id_extra_rows,
  SUM(CASE WHEN task_status NOT IN ('pending','completed','abandoned','validation_failed','failed') THEN 1 ELSE 0 END) AS invalid_task_status_rows,
  SUM(CASE WHEN trim(COALESCE(failure_reason,''))='' AND failure_reason IS NOT NULL THEN 1 ELSE 0 END) AS whitespace_only_failure_reason_rows
FROM messy_data;
